/* @lc app=leetcode id=1642 lang=kotlin */
class Solution { fun furthestBuilding(heights: IntArray, bricks: Int, ladders: Int): Int = java.util.PriorityQueue<Int>().let { pq -> IntArray(1) { bricks }.let { b -> (0 until heights.size - 1).takeWhile { i -> (heights[i + 1] - heights[i]).let { diff -> diff <= 0 || (pq.offer(diff) && (pq.size <= ladders || (b[0] - pq.poll()).also { b[0] = it } >= 0)) } }.size } } }